def configure(copy):
 for lang,t in copy.items():
  x=D[lang]
  for k in ('solutions','demo','security-deployment','project-intake'):
   t['labels'][k]=x[{'solutions':'solutions','demo':'demo','security-deployment':'security','project-intake':'intake'}[k]]
   t['navDesc'][k]={'solutions':x['solutionsLead'],'demo':x['demoLabel'],'security-deployment':x['controls'],'project-intake':x['intakeLead']}[k]
  group=next(g for g in t['navGroups'] if 'ai-infrastructuur' in g.get('keys',[]))
  group['keys']=['solutions','ai-infrastructuur','development','demo']
  web=next(g for g in t['navGroups'] if 'websites' in g.get('keys',[]))
  if 'games' not in web['keys']:web['keys'].append('games')
  for col in t['footer']:
   if 'contact' in col['keys']:col['keys']+=['project-intake','security-deployment']

