def render(lang,slug,g):
 e=g['E'];url=g['url'];x=D[lang];sec=g['sec_head'];blocks=g['blocks'];phero=g['phero'];page=g['page']
 def cards(items):return blocks([dict(abbr=f'{i+1:02d}',title=a,body=b) for i,(a,b) in enumerate(items)],'g3')
 def section(body):return '<section class="sec ai-brand-section"><div class="wrap">'+body+'</div></section>'
 def link(dest,label):return '<a class="btn btn-g" href="'+url(lang,dest)+'">'+e(label)+' ↗</a>'
 if slug=='solutions':
  title=x['solutionsTitle'];lead=x['solutionsLead'];body=section('<div class="grid g2">'+''.join('<a class="card" href="'+url(lang,SLUGS[i+1])+'"><span class="ab">0'+str(i+1)+'</span><h2 style="font-size:1.5rem">'+e(n)+'</h2><p>'+e(x['leads'][i])+'</p><span class="more">'+e(x['more'])+' →</span></a>' for i,n in enumerate(x['names']))+'</div>')
 elif slug.startswith('solutions/'):
  i=SLUGS.index(slug)-1;title=x['names'][i];lead=x['leads'][i]
  body=section(sec(x['problem'],x['problems'][i])+sec(None,x['deliver'])+'<ul class="checks">'+''.join('<li>'+e(s)+'</li>' for s in x['scopes'][i])+'</ul>')
  body+=section(cards([(x['measure'],x['measures'][i]),(x['controls'],x['controlBody']),(x['security'],x['processNote'])])+ '<div class="acts" style="margin-top:28px">'+link('demo',x['demo'])+link('security-deployment',x['security'])+'</div>')
 elif slug=='security-deployment':
  title=x['securityTitle'];lead=x['securityLead'];body=section(cards(x['securityCards']))
 elif slug=='demo':
  title=x['demoTitle'];lead=x['demoLead'];cfg={k:x[k] for k in ('fields','missing','noLines','review','empty','required')}
  body=section('<div class="interactive-demo" data-document-demo data-config="'+e(__import__('json').dumps(cfg))+'"><div><label for="sample-document">'+e(x['demoLabel'])+'</label><textarea id="sample-document" rows="9" maxlength="12000" spellcheck="false">'+e(SAMPLE)+'</textarea><p class="muted">'+e(x['demoHint'])+'</p><div class="acts"><button type="button" class="btn btn-p" data-extract>'+e(x['run'])+'</button><button type="button" class="btn btn-g" data-sample>'+e(x['sample'])+'</button></div></div><div><h2 style="font-size:1.3rem">'+e(x['result'])+'</h2><div data-extraction-result role="status" aria-live="polite"><p>'+e(x['empty'])+'</p></div></div></div>')
 else:
  title=x['intakeTitle'];lead=x['intakeLead'];labels=x['labels']
  def field(name,i,ty='text',req=False):return '<div class="fld"><label for="project-'+name+'">'+e(labels[i])+(' *' if req else '')+'</label><input id="project-'+name+'" name="'+name+'" type="'+ty+'" '+('required ' if req else '')+'maxlength="'+('160' if name=='email' else '120')+'" autocomplete="'+{'naam':'name','bedrijf':'organization','email':'email','telefoon':'tel'}.get(name,'off')+'"></div>'
  def select(name,i,opts):return '<div class="fld"><label for="project-'+name+'">'+e(labels[i])+'</label><select id="project-'+name+'" name="'+name+'">'+''.join('<option>'+e(v)+'</option>' for v in opts)+'</select></div>'
  cfg={k:x[k] for k in ('required','sending','success','error')}
  form='<form class="form project-form" data-project-form data-config="'+e(__import__('json').dumps(cfg))+'"><div class="grid g2">'+field('naam',0,req=True)+field('bedrijf',1,req=True)+field('email',2,'email',True)+field('telefoon',3,'tel')+select('project',4,x['types'])+field('tools',5)+select('timing',6,x['timings'])+select('budget',7,x['budgets'])+'</div><div class="fld"><label for="project-process">'+e(labels[8])+' *</label><textarea id="project-process" name="process" rows="5" maxlength="2400" required></textarea></div><input name="website_url" type="text" tabindex="-1" autocomplete="off" aria-hidden="true" class="project-honeypot"><p class="muted">'+e(x['privacy'])+' <a href="/privacy/?lang='+lang+'">'+e(x['privacyLink'])+'</a></p><button class="btn btn-p" type="submit">'+e(x['submit'])+'</button><p role="status" aria-live="polite" data-project-status></p></form>'
  body=section(form)
 body+='<section class="sec ai-brand-section"><div class="wrap"><div class="acts">'+link('project-intake',x['intake'])+'<a class="btn btn-g" href="/assets/marleo-company-profile.pdf" download>'+e(x['profile'])+' ↓</a></div></div></section>' if slug!='project-intake' else ''
 return page(lang,slug,title+' · Marleo',lead,phero(lang,slug,x['solutions'] if slug.startswith('solutions') else title,title,lead,acts=False)+body)

def home_resources(lang,g):
 x=D[lang];e=g['E'];url=g['url'];sec=g['sec_head']
 return '<section class="sec ai-brand-section"><div class="wrap">'+sec(None,x['homeTitle'],x['homeLead'])+'<div class="grid g3">'+''.join('<a class="card" href="'+url(lang,k)+'"><h3>'+e(x[v])+'</h3><span class="more">'+e(x['more'])+' ↗</span></a>' for k,v in [('solutions','solutions'),('demo','demo'),('security-deployment','security')])+'</div><div class="acts" style="margin-top:28px"><a class="btn btn-p" href="'+url(lang,'project-intake')+'">'+e(x['intake'])+'</a><a class="btn btn-g" href="/assets/marleo-company-profile.pdf" download>'+e(x['profile'])+' ↓</a></div></div></section>'

def case_section(lang,g):
 x=D[lang];e=g['E'];url=g['url']
 return '<section class="sec ai-brand-section"><div class="wrap">'+g['sec_head'](None,x['caseTitle'],x['caseLead'])+'<div class="grid g2">'+''.join('<a class="card" href="'+url(lang,'projecten/'+slug)+'"><span class="ab">'+e(x['caseTags'][i])+'</span><h3>'+e(x['caseTitles'][i])+'</h3><p>'+e(x['caseBodies'][i])+'</p><span class="more">'+e(x['caseCta'])+' →</span></a>' for i,slug in enumerate(['trusttap','pain-du-mie']))+'</div></div></section>'

